import { attachSaveStatus } from "./save-status.js";
import { createTrailingTask } from "./trailing-task.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  let navigationVersion = 0;

  function leave() {
    const leaving = current;
    current = null;
    if (leaving) leaving.stop();
    renderDocument(null);
    if (leaving) leaving.save.flush();
  }

  function close() {
    ++navigationVersion;
    leave();
  }

  return {
    open(id) {
      const request = ++navigationVersion;
      leave();
      if (request !== navigationVersion) return;

      const visit = {};
      const opened = {
        id,
        text: store.read(id),
        visit,
        save: createTrailingTask((savedId, text) => store.write(savedId, text), 120, timers),
        stop: attachSaveStatus(store, id, renderStatus),
      };
      current = opened;
      renderDocument({ id, text: opened.text });
    },
    edit(text) {
      if (!current) return;
      current.text = text;
      current.save.push(current.id, text);
    },
    selection() {
      return current && { id: current.id, text: current.text, visit: current.visit };
    },
    flush(visit) {
      if (current && current.visit === visit) current.save.flush();
    },
    isActive(visit) {
      return !!current && current.visit === visit;
    },
    close,
  };
}

